python - <<'EOF'
import sys
sys.path.insert(0,'scripts')
import numpy as np, pandas as pd
from miner3_20260730_harness import ASSETS, evaluate, load_closes, load_macro
closes=load_closes(); macro=load_macro()

def beta(r_a, r_b, win, self_skip=False):
    df=pd.concat([r_a.rename('x'), r_b.reindex(r_a.index).rename('y')],axis=1).dropna()
    if len(df)<win+5: return pd.Series(np.nan,index=r_a.index)
    return (df['x'].rolling(win).cov(df['y'])/df['y'].rolling(win).var()).reindex(r_a.index)

def beta_ratio(r_a, r_b, w1, w2):
    # beta short / beta long (beta momentum)
    df=pd.concat([r_a.rename('x'), r_b.reindex(r_a.index).rename('y')],axis=1).dropna()
    if len(df)<w2+5: return pd.Series(np.nan,index=r_a.index)
    b1=df['x'].rolling(w1).cov(df['y'])/df['y'].rolling(w1).var()
    b2=df['x'].rolling(w2).cov(df['y'])/df['y'].rolling(w2).var()
    return (b1/b2.replace(0,np.nan)).reindex(r_a.index)

def kaufman_eff(close,n=20):
    chg=(close-close.shift(n)).abs()
    vol=close.diff().abs().rolling(n).sum()
    return chg/vol.replace(0,np.nan)

def coppock(close,long=14):
    # long-term ROC weighted
    r=close.pct_change(long)
    return r.rolling(10).mean()

def tri_x(close,fast=5,slow=120):
    ma1=close.rolling(fast).mean(); ma2=close.rolling(slow).mean()
    return ma1/ma2.replace(0,np.nan)-1

def highlow_var(close,n=20):
    r=close.pct_change()
    return r.rolling(n).std()

cands={
 'rate_beta_ratio_10x60':{a:beta_ratio(closes[a].pct_change(),closes['US10Y'].pct_change(),10,60) for a in closes if a!='US10Y'},
 'jpy_beta_ratio_10x60':{a:beta_ratio(closes[a].pct_change(),macro['USDJPY'].pct_change(),10,60) for a in closes},
 'gold_beta_60':{a:beta(closes[a].pct_change(),closes['XAU'].pct_change(),60) for a in closes if a!='XAU'},
 'kaufman_variant_10':{a:kaufman_eff(closes[a],10) for a in closes},
 'coppock_14':{a:coppock(closes[a],14) for a in closes},
 'tri_x_5x120':{a:tri_x(closes[a],5,120) for a in closes},
}
for name,vals in cands.items():
    evaluate(closes,vals,name,horizon=10)
    print()
EOF

