"""miner_1 2031-06-12: validation library (shared by candidate scripts)."""
import numpy as np
import pandas as pd
from pathlib import Path

VISIBLE_END = pd.Timestamp('2031-06-12')
STOCK_DIR = Path('../persistent/stock_data')
INDEX_DIR = Path('../persistent/index_data')
ASSETS = ['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX',
          'XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']

def load_closes():
    closes = {}
    for a in ASSETS:
        f = STOCK_DIR / f'{a}.csv'
        if not f.exists():
            f = INDEX_DIR / f'{a}.csv'
        df = pd.read_csv(f, parse_dates=['date']).sort_values('date')
        df = df[df['date'] <= VISIBLE_END].set_index('date')
        closes[a] = df['close'].astype(float)
    return closes

def load_ohlcv():
    out = {}
    for a in ASSETS:
        f = STOCK_DIR / f'{a}.csv'
        if not f.exists():
            f = INDEX_DIR / f'{a}.csv'
        df = pd.read_csv(f, parse_dates=['date']).sort_values('date')
        df = df[df['date'] <= VISIBLE_END].set_index('date')
        out[a] = df
    return out

def load_macro(name):
    df = pd.read_csv(INDEX_DIR / f'{name}.csv', parse_dates=['date']).sort_values('date')
    df = df[df['date'] <= VISIBLE_END].set_index('date')
    return df['close'].astype(float)

def returns(closes, start='2020-03-01'):
    rets = pd.DataFrame({a: closes[a].pct_change() for a in ASSETS}).dropna()
    return rets[rets.index >= start]

def compute_ic(factor_vals, forward_rets, min_dates=60, min_assets=8):
    common = sorted(set(factor_vals.index) & set(forward_rets.index))
    ics, dates_ok = [], 0
    for d in common:
        f = factor_vals.loc[d]; r = forward_rets.loc[d]
        valid = f.notna() & r.notna()
        if valid.sum() >= min_assets:
            dates_ok += 1
            fv = f[valid].rank().values; rv = r[valid].rank().values
            if np.std(fv) > 0 and np.std(rv) > 0:
                ics.append(np.corrcoef(fv, rv)[0, 1])
    ics = np.array(ics)
    if len(ics) < min_dates:
        return {'IC': 0.0, 'ICIR': 0.0, 'n': len(ics), 'dates_ok': dates_ok}
    mu = ics.mean(); sd = ics.std()
    icir = mu / sd * np.sqrt(len(ics)) if sd > 0 else 0.0
    return {'IC': float(mu), 'ICIR': float(icir), 'n': int(len(ics)), 'dates_ok': dates_ok}

def coverage(fv):
    cov = float(fv.notna().sum().sum()) / (fv.shape[0] * fv.shape[1])
    dates_ok = float((fv.notna().sum(axis=1) >= 8).mean())
    return cov, dates_ok

def turnover(fv):
    s = np.sign(fv.rank(axis=1).sub(fv.shape[1] / 2)).fillna(0)
    diff = (s.diff() != 0).mean().mean()
    return float(diff)

def decay_ic(factor_vals, rets, horizons=(1, 2, 3, 5, 10, 20), min_dates=30):
    out = {}
    for h in horizons:
        fwd = rets.shift(-h).rolling(h).mean()
        r = compute_ic(factor_vals, fwd, min_dates=min_dates)
        out[str(h)] = r['IC'] if r['n'] > 0 else 0.0
